update content_bodies set title = '2021年を振り返る＿Looking back on 2021 with instagram photos', description = '★English caption below★

弘前を大切に想う方々がインスタグラム上で「#ecomeonhirosaki」を付けて発信してくださった素敵な写真による「２０２１年スライドショー動画」をお届けします。
季節の移り変わりとともに変化する美しい風景など、弘前の街に潜在する素晴らしい魅力をじっくりとご覧ください。

This slideshow is made up of wonderful photos posted on Instagram with #ecomeonhirosaki by locals and tourists who love Hirosaki.
Please take your time to view the beautiful seasonal scenery and other hidden spots of Hirosaki city.' where id = '2-OY6-riKW0eeQ8c0aTHd';
