update content_bodies set title = 'The Four Seasons of Niyodo River', description = '奇跡の清流―仁淀川。
高知県の仁淀川は、透明度と青さから『仁淀ブルー』と呼ばれ、四季折々の美しさで訪れる人の心を魅了します。
神秘的な自然の風景と、この地域の人々の暮らし、地域で継承されてきた神事などをご堪能ください。
本映像は、仁淀川水系を長年撮影し続けてきたネイチャーカメラマン・高橋宣之氏による貴重な映像です（一部を除く）。' where id = '_1tZWBDexkzeZjXUysNRP';
update content_bodies set title = 'The Four Seasons of Niyodo River', description = 'A miraculous clear stream - Niyodo River.
The Niyodo River in Kochi Prefecture is known as ''Niyodo Blue'' for its transparency and blueness, captivating visitors with its beauty throughout the four seasons.
Enjoy the mystical natural landscapes, the lives of the people in this region, and the traditional rituals that have been passed down in the area.
This footage is a valuable collection by nature photographer Nobuyuki Takahashi, who has been capturing the Niyodo River system for many years (with some exceptions).' where id = 'AQQQQ-wmtUcudRyyzmn6U';
