update content_bodies set title = '川越 - KAWAGOE -', description = '2人の時間めぐりの旅

最終日に訪れた街「小江戶川越」
明日はメキシコに帰らなくてはならい 2 人
楽しかった日本の滞在期間を思い、ちょっと寂しい

浴衣を着て外に出ると街の様子が変わっていることに気づく 2 人 
さっきと違って、街に人々が右往左往歩いている 
まるで時間の流れを歩いているようだ
さあ、時間巡りの散歩に行こう！

どうやら、自分の「時」をみつけることができる場所があるらしい
探してみよう

ゆったりと時間が流れる
過去に行きすぎたかな・・・
とても懐かしい気がする空間

やっぱり「時」を戻ることはできないのかな・・・

どうしても見つからない「時」 
最後に「時の鐘」まで行ってみよう

「時の鐘」
そうか、過去なんかより未来が大切なのかもしれない
2 人で未来を進んでいくこと、だから一瞬一瞬が大切なんだ
ここから始めよう
僕たち私たちの未来を' where id = 'y1v96WOGM2d5rFA-wzk-P';
update content_bodies set title = 'Kawagoe - KAWAGOE -', description = 'A journey through time for two

The town we visited on the last day, "Koedo Kawagoe"
Two people who must return to Mexico tomorrow
Feeling a bit lonely as we think about the enjoyable time spent in Japan

As we step outside in our yukatas, we notice the town has changed
Unlike before, people are bustling about in the streets
It feels as if we are walking through the flow of time
Let''s go for a stroll through time!

It seems there is a place where we can find our own "time"
Let''s search for it

Time flows gently
Have we gone too far into the past...
This space feels so nostalgic

After all, is it really impossible to go back in "time"...

The "time" we just can''t seem to find
Let''s head to the "Time Bell" as a last resort

"Time Bell"
I see, perhaps the future is more important than the past
Moving forward into the future together, that''s why every moment is precious
Let''s start from here
Our future, yours and mine' where id = 'lvlw1Y2tp8WDId9gVl6Is';
update content_bodies set title = '鎌倉 - KAMAKURA -', description = '鎌倉、時を楽しむ旅がある
1人で訪れた街は鎌倉。寂しいけど、1人散歩を楽しむことに。
祠、鳥居、時が刻まれた建物。不思議な竹林。
わくわくしてくるけど・・・やっぱり寂しいな。
電車に乗ると、そこには・・・
2人だと、また景色がちがうようにみえる鎌倉。
今日は楽しかった。
ここから始まる、私たちの旅。' where id = 'ymHQbh1UctPLDDquesSaY';
update content_bodies set title = 'Kamakura - KAMAKURA -', description = 'Kamakura, a journey to enjoy time.
The city I visited alone is Kamakura. It''s lonely, but I enjoy walking alone.
Shrines, torii gates, buildings marked by time. A mysterious bamboo grove.
It''s exciting, but... it''s still lonely.
When I get on the train, there it is...
With two people, Kamakura looks different again.
Today was fun.
This is where our journey begins.' where id = '7R8MjsSqoBCnqbCii6Gya';
update content_bodies set title = '【盆踊り編】よみがえる下風呂小唄 〜下風呂温泉郷のいま〜（青森県風間浦村）', description = 'かつて温泉郷で歌い継がれていたものの、時代の流れとともに忘れ去られてしまった「下風呂小唄」。口伝えでかろうじて残されていたその歌に、伴奏をつけ蘇らせるプロジェクトが発足。2022年夏に新たに収録し蘇った「下風呂小唄」に、温泉郷旅館の女将で組織する「下風呂温泉おかみの会」の皆さんが中心となって振り付けを考案。2023年夏、「下風呂温泉郷納涼夜店祭り」にて初披露され、温泉郷の盆踊りとして復活しました。

映像監督：藤代雄一朗

【前編】よみがえる下風呂小唄 〜下風呂温泉郷のいま〜（青森県風間浦村）
https://youtu.be/k2QL9G3Qjpk
【総集編】よみがえる下風呂小唄 〜下風呂温泉郷のいま〜（青森県風間浦村）
https://youtu.be/oR9MR9gTODA

下北ゆかい村公式HP
https://www.yukaimura.com/

下北ゆかい村は、青森県下北郡風間浦村の観光・温泉・食材などのプロモーションをしています。昭和感漂う下風呂温泉郷、生きたまま水揚げされる風間浦鮟鱇、イカ釣り船の漁火など、魅力的な村です。' where id = 'RUj_OJn_dyjWgLJtfEDzF';
update content_bodies set title = '[Bon Odori Edition] The Revived Shimofuro Kouta - The Present of Shimofuro Onsen Town - (Kazamaura, Aomori Prefecture)', description = 'Once sung in the hot spring town, the ''Shimofuro Kouta'' was forgotten over time. A project was launched to revive this song, which had barely survived through oral tradition, by adding accompaniment. In the summer of 2022, the newly recorded ''Shimofuro Kouta'' was choreographed by the members of the ''Shimofuro Onsen Okami Association,'' consisting of the proprietresses of the hot spring inns. In the summer of 2023, it was first unveiled at the ''Shimofuro Onsen Town Summer Night Market Festival,'' marking its revival as a Bon Odori dance in the hot spring town.

Director: Yuichiro Fujishiro

[Part 1] The Revived Shimofuro Kouta - The Present of Shimofuro Onsen Town - (Kazamaura, Aomori Prefecture)
https://youtu.be/k2QL9G3Qjpk
[Compilation] The Revived Shimofuro Kouta - The Present of Shimofuro Onsen Town - (Kazamaura, Aomori Prefecture)
https://youtu.be/oR9MR9gTODA

Shimokita Yukai Village Official Website
https://www.yukaimura.com/

Shimokita Yukai Village promotes tourism, hot springs, and local ingredients in Kazamaura, Shimokita District, Aomori Prefecture. It is an attractive village with a Showa-era atmosphere, live-caught Kazamaura anko, and the fishing lights of squid fishing boats.' where id = '_p2qNrZsLrscdnytZf4Vd';
