update content_bodies set title = 'Directly Managed Tea Shop 🍵 ''Shinryoku Sabo'' Offers Refreshing Summer with Tea and Sweets 🍃', description = '''If you want to go!'' please comment ''🍵'' ♪

A directly managed store by a tea farmer producing Ise tea in Matsusaka City, Mie Prefecture,
''Shinryoku Sabo'' Iinan Main Store offers freshly brewed tea, Japanese sweets that pair well with tea,
and sweets made with tea 🍡

