💡スタッフさんがマンツーマンで優しく教えてくれるから、初心者でもお子様でも安心です。
💡ガスバーナーでチタンを炙って、綺麗に色がついていく様子はとても神秘的！
💡体験後にはチタンカップでコーヒータイム！

