update content_bodies set title = 'Rainbow Titanium Coloring Experience! "Craft Armadillo"', description = '#Mie no Imakoko Travel

A unique rainbow-colored shine in the world!
Rainbow titanium coloring experience!

〜・〜・〜・〜・〜・〜・〜・〜・〜

【Content】
💡Experience the rainbow titanium coloring unique to the motorsport town of "Suzuka City"!
💡You can experience it at the factory of "Craft Armadillo," which manufactures titanium products such as motorcycle racing mufflers.
💡By heating, you can enjoy a special experience that utilizes the properties of titanium, which changes color depending on the temperature.
💡You can choose from several courses, including cups, badges, and keychains.
💡Create your own original titanium product that is one of a kind in the world.
💡The staff will kindly teach you one-on-one, so it''s safe for beginners and children.
💡The process of heating titanium with a gas burner and watching it change color is very mystical!
💡After the experience, enjoy coffee time with your titanium cup!

