"Koubenomiya Yomou Shrine" (こうべのみやよもうじんじゃ), famous for passing prayers, attracts visitors from all over the country.
Not only for passing prayers, but also because it is the God of Wisdom, they perform blessings for helmets, which is unique to this shrine in Mie Prefecture✨

