update content_bodies set title = '【速報】#かざはやの里 の藤が見頃です！', description = '三重県津市にあるかざはやの里の藤は三重県を代表する藤の名所の一つ。

「白甲比丹藤」「紫甲比丹藤」「紅藤」「口紅藤」「六尺藤」「九尺藤」「長崎一歳藤」
「八重黒龍藤」「黒龍藤」「白野田藤」の10種類1800本が
10,000㎡の10種類の藤棚と58,000㎡の園内の立木に4月下旬～5月上旬に開花します💜

藤の種類にもよりますが、早咲きは一部落花が始まり、これから開花する蕾もたくさんありますよ☺

季節の花が浮かべられる花手水も写真映えまちがいなし！


📅2024年4月13日(土)～2024年5月6日(月)※無休
📍津市戸木町4096伊勢温泉ゴルフクラブ内
⌚8:00～18:00
🎫開花状況により変動
🚃GW期間の土日など近鉄「久居駅」東口よりシャトルバスが運行
🚙伊勢自動車道「久居IC」より車で5分、国道165号青山方面、戸木口交差点、
コスモスショッピングセンター右折、風早池に向かい、
社会福祉法人正寿会「かざはや」の看板左折


#kankomie #visitmie #観光三重 #三重観光 #三重 #津市 #中勢 #あじさい #紫陽花 #花 #春の花 #春
#花手水 #GWおでかけ #三重おでかけ #花トリップ #flower #絶景' where id = 't6F3olxh8u7Nay4Uy-MZA';
update content_bodies set title = '[Breaking News] The wisteria at #KazahayanoSato is in full bloom!', description = 'The wisteria at Kazahayano Sato in Tsu City, Mie Prefecture, is one of the representative wisteria spots in Mie Prefecture.

Ten varieties of wisteria, including "Shirakouhitan Fuji," "Murasakikouhitan Fuji," "Benifuji," "Kuchibeni Fuji," "Rokushaku Fuji," "Kyushaku Fuji," "Nagasaki Isai Fuji," "Yaekokuryu Fuji," "Kokuryu Fuji," and "Shiranoda Fuji," totaling 1,800 plants, will bloom from late April to early May across 10,000㎡ of 10 different wisteria trellises and 58,000㎡ of standing trees in the garden 💜

Depending on the variety of wisteria, some early bloomers have already started to drop their flowers, and there are many buds that will bloom soon ☺

The seasonal flower water offerings are sure to be a hit for photos!

📅 April 13, 2024 (Saturday) to May 6, 2024 (Monday) *Open every day
📍 4096 Toki-cho, Tsu City, inside Ise Onsen Golf Club
⌚ 8:00 AM to 6:00 PM
🎫 Subject to change depending on blooming conditions
🚃 Shuttle buses will operate from the east exit of Kintetsu "Hisai Station" on weekends during the Golden Week period
🚙 5 minutes by car from Ise Expressway "Hisai IC," heading towards Aoyama on National Route 165, at the Toki-guchi intersection, turn right at Cosmos Shopping Center, head towards Kazahayai Pond, and turn left at the sign for the social welfare corporation Seijukai "Kazahaya"

