update content_bodies set title = '一度は食べたい！感動●●　#Marbre Lapin', description = '【一度は食べたい！売り切れ必至の感動●●】

早く行かないとすぐに売り切れちゃう！
鈴鹿市の大人気パン屋さん【Marbre Lapin】

一番人気は、３日間かけて作る 超こだわりのクロワッサン🥐
ゆっくり大切に何層にも重ね合わせ丁寧に焼くことで
外はパリッパリ！中はしっとり！の極上食感に！

「目でも楽しめるパン屋さんに」という想いから
パン屋さんでは珍しいオープンキッチンスタイル。
パン作りを間近で見られるのも楽しみのひとつです✨

人気パンはすぐに売り切れてしまう日も。
午前中に行くのがオススメです💡

