[Recommended for winter! Established 150 years ago, the taste of a long-established Japanese confectionery shop
is exquisite.]

Warm even in the cold winter ♨􀀀
Enjoy exquisite zenzai with a mild sweetness made using Tamba Dainagon red beans
Hananosha is a long-established Japanese confectionery shop that has been in business for over 150 years.

You can enjoy the taste of a long-established restaurant in the attached cafe space.
Especially in winter, this exquisite zenzai is said to be an overwhelmingly popular menu item!

Besides,
Seasonal sweets and matcha set, shiratama,
During the summer, you can also enjoy shaved ice and matcha ice cream.

Check here for more details👇
https://hananoya.info

