[You are sure to pass! “Win” the exam! A shrine where the god of victory resides]

A must-see for examinees! A shrine that prays for victory, known only to those in the know ⛩
[Katsuhayahi Shrine] is located in Suzuka City, Mie Prefecture.
A power spot lined with auspicious kanji✨

"勝＝Victory" "速＝Speed" "日＝Rising Sun"
As the name suggests, it enshrines the "god of victory and luck".
People from all over the country come to pray for success and victory!

Located just 3 minutes walk from the nearest Kintetsu Shirako Station.
When you pass through the torii gate, the atmosphere changes drastically.
The approach lined with lanterns and the grounds surrounded by greenery will soothe your soul 🙏
Be sure to stop by before the match!
