update content_bodies set title = '開運を導く神様が宿る！　#椿大神社', description = '【開運を導く神様が宿る！パワースポット】

森の中にそびえる日本最古の神社⛩
古くから「椿さん」の愛称で親しまれている【椿大神社】は
開運みちびきの神様として知られる猿田彦大神を祀り、
多くの方が交通安全や無病息災、商売繫昌などを祈願されます。

参道は木々が生い茂り神聖な空気が流れ、
冬には境内のあちこちで椿の花がほころび、
四季折々に見られる自然美も大きな見どころのひとつ。

境内には縁結びの神社や恋愛成就のパワースポットも！
新たな年の始まりに参拝したいですね😌🙏

詳しくはコチラからcheck👇
