update content_bodies set title = 'インスタ映え必至の花手水！ #金井神社 #花手水 #観光三重 #vlog #三重', description = '【初詣にもオススメ！色とりどりの花と風車のカラフル神社】
カラフルで写真映えすると話題！
華やかなに装飾された境内の【金井神社】は
鎮座800年を超える歴史ある神社⛩
季節ごとに入れ替わるお花をふんだんに使った花手水は
毎日お手入れされ、お花の種類や飾り付けが少しずつ変化するのだそう！
また絵馬の代わりに願い事が書かれた風車がならぶ
華やかな境内も見どころのひとつ。
身も心も癒される神社、
年始の初詣にぜひ参拝してみてくださいね😊🙏
詳しくはコチラからcheck👇
https://www.kanaijinjya.com
📸金井神社
📍三重県いなべ市員弁町北金井９１１
