[Recommended for New Year''s visit! Colorful shrine with colorful flowers and windmills]
It is popular for being colorful and photogenic!
[Kanai Shrine] has a gorgeously decorated precinct.
A historic shrine that has been in existence for over 800 years⛩
Flower chozui is made with plenty of flowers that change with the seasons.
It is maintained every day, and the types of flowers and decorations change little by little!
Also, instead of votive tablets, there are windmills with wishes written on them.
The gorgeous precincts are also one of the highlights.
A shrine that soothes the body and soul,
Please come and visit the shrine at the beginning of the year 😊🙏
Check here for more details👇
https://www.kanaijinjya.com
📸Kanai Shrine
📍911 Kitaganai, Inabe-cho, Inabe City, Mie Prefecture
