update content_bodies set title = '薪火で焼く！ホットドッグ！ #観光三重 #vlog #三重', description = '【薪のいい香り！噛んだ瞬間 肉汁があふれるホットドッグ】
ソーセージもパンも薪火で焼くから香ばしい！
いなべ市役所の隣・にぎわいの森にある「食肉加工屋FUCHITEI」は
絶品のホットドッグが食べられるお店🌭
噛んだ瞬間に自家製ソーセージから溢れ出した肉汁を
焼き目のついたパンが逃すことなく受け止めます✨
添加物を使わないのがフレンチシェフでもある店主のこだわり。
ソーセージのほかパテやテリーヌも店内の工房で作られています🧑🍳
詳しくはコチラからcheck👇
