update content_bodies set title = '感動の光のトンネル　#なばなの里 #観光三重 #vlog #三重', description = '感動の光のトンネル「なばなの里イルミネーション」
冬が特にオススメ！
日本夜景遺産や世界の絶景にも選ばれた『光のトンネル』や
圧巻の水上イルミネーションが輝く『光の大河』など、
国内最大級のイルミネーションが夜空を照らします✨
広大な庭園が彩り豊かな光に包まれ
幻想的な雰囲気漂うデートや家族での思い出づくりに最適！
ぜひロマンチックなひとときを…♡
