Impressive tunnel of light “Nabana no Sato Illumination”
Especially recommended in winter!
``Tunnel of Light,'''' which has been selected as a Japan Night View Heritage Site and one of the world''s most
spectacular views.
The ``Taiga of Light'''' with spectacular water illuminations, etc.
Japan''s largest illumination lights up the night sky✨
A vast garden surrounded by colorful light
Perfect for a date with a magical atmosphere or for making memories with your family!
Have a romantic moment...♡
Check here for lighting hours👇
https://www.nagashima-onsen.co.jp/nabana/illumination/info/illumi_tentou_time.html
📸Nabana no Sato
📍270 Komae Urushibatake, Nagashima Town, Kuwana, Mie Prefecture
