update content_bodies set title = 'クマ型の最中がキュート！#東海道関宿 #gute #観光三重 #vlog #三重', description = '食べられるのは日本でココだけ！「gute」
📍東海道関宿/亀山市関町
@gute.___
レトロな街並みで話題の関宿にある
古民家を改装したオシャレな和カフェ。
実は、可愛いクマ型もなか専門店なんです✨
甘さ控えめの粒あんを炙りたてのサクサク皮が包んだ一品は
食べ歩きにもお土産にもオススメ！
関宿を観光したらぜひ立ち寄りたいお店です🐻
