This is the only place you can eat it in Japan! "gute"
📍Tokaido Sekijuku/Kameyama City Sekimachi
@gute.___
Located in Sekijuku, which is popular for its retro streetscape.
A stylish Japanese cafe in a renovated old folk house.
Actually, it''s a store specializing in cute bear-shaped monaka✨
A dish of lightly sweetened bean paste wrapped in freshly grilled crispy skin.
Recommended for eating while walking or as a souvenir!
This is a shop you should definitely stop by when sightseeing in Sekijuku 🐻
