update content_bodies set title = '伊賀忍者をイメージして作られた名物【本流 霧隠れうどん】#池澤湯', description = '忍者の里・伊賀で立ち寄るならココ！「うどん屋 池澤湯」
📍伊賀市上野
メディアにもよく取り上げられる三重県の人気店✨
伊賀忍者をイメージして作られた名物【本流 霧隠れうどん】は
真っ白のお出汁の中から真っ黒な太麺が出現するんです！
伊賀牛コロッケをトッピングするのがお店のオススメ😋
店内はたくさんの忍者グッズで外国人観光客にも大人気！
家族旅行はもちろん、カップルやお友達でも楽しめる
伊賀を旅するには外せないスポットです💡
