If you want to stop by Iga, the ninja village, this is the place! "Udon restaurant Ikezawayu"
📍Ueno, Iga City
A popular store in Mie Prefecture that is often featured in the media✨
The specialty [Mainstream Kirigakure Udon] is made with the image of Iga ninjas,
and thick black noodles emerge from the pure white soup stock!
The restaurant recommends topping it with Iga beef croquette 😋
The store has a lot of ninja goods and is very popular among foreign tourists!
This is a must-see spot for families, couples, and friends when traveling to Iga.
