update content_bodies set title = 'Hot Topic! ''Mokumoku'' Cream Soda @ Kyoguchi Coffee House ☕', description = '''Mokumoku'' cream soda is making waves⁉️
In a nostalgic retro café,
we offer stunningly beautiful sweets 🍮✨

The secret of Mokumoku is... dry ice 🧊
The owner’s family runs a company that sells dry ice,
and they have been serving this style since opening.
In addition to cream soda, coffee floats
are also served with the Mokumoku effect 💁‍♀️🎶

All sweets and food are handmade by the owner,
and the lunch menu was incredibly cost-effective...♡

*Desserts like pudding are served from 14:30

Kyoguchi Coffee House

