update content_bodies set title = '光り輝くネオンサインがSNSで話題沸騰中!?「一乃湯」', description = '―――――――――――――――――――――

光り輝くネオンサインがSNSで話題沸騰中!?
創業70年以上の歴史あるレトロ銭湯をご紹介。

上野城下町を歩いていくと、一際異彩を放った外観で
「一乃湯」のネオン看板が見えてきます！

館内や銭湯内はまるで昭和にタイムスリップしたかのよう。
このあふれるレトロ感がたまりません🥺✨

今年7月、創業から三代にわたった運営を、
「銭湯を日本から消さない」をモットーとする、
銭湯継業グループ「ゆとなみ社」が受け継いだとのこと。
時代に合わせて進化を続ける「一乃湯」に目が離せません👀

※館内・銭湯内は特別な許可を得て撮影しています。

-------------------------------------------

📍レトロ銭湯一乃湯
@ichinoyu_iga

