update content_bodies set title = 'The Shining Neon Sign is Making Waves on Social Media!? ''Ichinoyu''', description = '――――――――――――――――――――

Is the shining neon sign making waves on social media!?
Introducing a retro bathhouse with over 70 years of history.

As you walk through the Ueno castle town, you will see the neon sign of ''Ichinoyu'' standing out with its unique appearance!

Inside the building and the bathhouse, it feels like you have time-traveled back to the Showa era.
This overflowing retro vibe is irresistible 🥺✨

In July of this year, the management, which has been passed down through three generations since its founding, was taken over by the bathhouse succession group ''Yutanami-sha'', which has the motto of ''Not letting bathhouses disappear from Japan''.
You can''t take your eyes off ''Ichinoyu'', which continues to evolve with the times 👀

*Photography inside the building and bathhouse is done with special permission.

-------------------------------------------

📍Retro Bathhouse Ichinoyu
@ichinoyu_iga

Inquiries▶070-3352-2440
Location▶1762 Nihinmachi, Ueno, Iga City, Mie Prefecture
Business Hours▶14:00 - 23:00 (Reception until 22:30)
Closed▶Thursdays
Parking▶14 cars
Access▶About a 12-minute walk from Iga Railway ''Hirokoji Station''

-------------------------------------------

If you found this post interesting,
please give it a ''like & save'' ♡
Details of each spot are also introduced on ''Tourism Mie''!  

