update content_bodies set title = 'Enjoy！ MIE National Park～', description = '三重県には国立公園が2つ、そして国定公園が2つ存在します。

伊勢神宮を擁しリアス海岸が特徴的な「伊勢志摩国立公園」
奥深い自然と歴史が結びついた「吉野熊野国立公園」
交通の便がよく鈴鹿山脈と湯の山温泉が自慢の「鈴鹿国定公園」
渓谷と連なる山々の雄大さをどちらも楽しめる「室生赤目青山国定公園」

どの公園にも、それぞれ違った魅力があります。
三重の国立・国定公園で、ここにしかない自然を楽しんでみませんか？

三重県国立国定公園特設サイト
https://www.kankomie.or.jp/special/nationalpark/index.html' where id = 'P3js2XljUgvnVnpzc8VGl';
update content_bodies set title = 'Enjoy! MIE National Park～', description = 'Mie Prefecture has two national parks and two quasi-national parks.

The "Ise-Shima National Park" featuring the Ise Grand Shrine and a ria coastline.
The "Yoshino-Kumano National Park" where deep nature and history are intertwined.
The "Suzuka Quasi-National Park" known for its good transportation and the Suzuka Mountains and Yunoyama Onsen.
The "Muro-Akame-Aoyama Quasi-National Park" where you can enjoy the grandeur of mountains connected by valleys.

Each park has its own unique charm.
Why not enjoy the nature that can only be found in Mie''s national and quasi-national parks?

Mie Prefecture National and Quasi-National Park Special Site
https://www.kankomie.or.jp/special/nationalpark/index.html' where id = 'DKXOQXWcIJJh70IrO94pZ';
