update content_bodies set title = 'FEEL VIBRATIONS - Experience the Emotion with ''Mie Travel''! - #Mie Tourism PR Video', description = 'Mie Prefecture collaborates with ''Discover Japan''! Feel as if you are actually traveling.
Please experience the unique ''VIBRATION'' of Mie!

【Video Concept】
With the concept of ''FEEL VIBRATIONS'', we introduce various ''VIBRATIONS'' emitted by Mie Prefecture from the perspective of travelers experiencing them firsthand, such as the ''mystical waves'' of Ise Jingu and Kumano Kodo, the ''breath'' of history rooted in Takada Honganji and Iga, and the ''heartbeat'' of the sea felt in Ago Bay.

