update content_bodies set title = '鬼ヶ城センターの中を紹介します(熊野市)｜観光三重｜三重県の観光・旅行情報', description = '世界遺産のまち、三重熊野の玄関口にある鬼ヶ城センターは、熊野尾鷲自動車道・熊野大泊インターすぐ。熊野の四季を感じられるお食事と特産品を取りそろえた、まるごと熊野を体感できる施設です。世界遺産の一部でもあり国の天然記念物及び名勝「鬼ヶ城」に隣接し、熊野古道「松本峠」にも近く、熊野古道ウォークも簡単に楽しめます！

お土産・お食事・鬼ヶ城！熊野にお越しの際は、ぜひお立ち寄りください。熊野が好き～♬

