update content_bodies set title = 'Introducing the Oki Castle Center (Kumano City) | Tourism Mie | Mie Prefecture Travel Information', description = 'The Oki Castle Center, located at the gateway to the World Heritage town of Kumano, Mie, is right next to the Kumano Owase Expressway and the Kumano Oodai Interchange. It is a facility where you can experience all of Kumano, offering meals and local specialties that allow you to feel the four seasons of Kumano. Adjacent to the World Heritage site and national natural monument and scenic spot ''Oki Castle'', it is also close to the Kumano Kodo ''Matsumoto Pass'', making it easy to enjoy a walk on the Kumano Kodo!

Souvenirs, meals, and Oki Castle! If you visit Kumano, please stop by. We love Kumano~ ♬

