update content_bodies set title = 'Opened on April 5, 2019! Introducing the ''Matsusaka City Tourist Exchange Center, the Town of Great Merchants'' (Matsusaka City) | Kankou Mie | Mie Prefecture Tourism and Travel Information', description = 'The Tourist Exchange Center, which serves as a base for exploring the town, opened on April 5, 2019, showcasing various attractions of Matsusaka, including its history, culture, and food!

At the facility, you can learn in depth about the charm of Matsusaka''s history and culture through exhibitions and video displays that incorporate the vibrancy of the Sangu Kaido, the great figures of Matsusaka, and Matsusaka merchants. You can also find information about tourist spots in the city, Matsusaka products, and restaurants. By using the town walking arrangement service (information terminals), you can create your own original sightseeing course.

As a guide for walking around the city, utilize the Tourist Exchange Center to learn about history and culture, create your own route map, and then just enjoy to the fullest! You can also buy souvenirs at the center, so be sure to stop by again at the end!

