update content_bodies set title = 'Summer Festivals in TOHOKU JAPAN（東北の夏祭り）', description = 'The summer festivals in the six prefectures of Tohoku region will be dynamically expressed with viewpoints and staging that would otherwise be impossible to see.
Aomori Nebuta Festival, Morioka Sansa Odori Festival, Sendai Tanabata Festival, Akita Kanto Festival, Yamagata Hanagasa Festival, Soma Nomaoi.
TOHOKU JAPAN consists of Aomori, Iwate, Miyagi, Akita, Yamagata and Fukushima prefectures.

CG：ＷＯＷ inc.
Music:Mitsu the Beats
Produced by Reconstruction Agency
 
東北６県の夏祭りを大胆かつ今までにない視点で表現したノンバーバル（非言語）の動画です。' where id = 'bN_6mDqFnfzexidf5eaVt';
