update content_bodies set title = 'Winter in Nagano, Japan - Festivals, Japanese Food and Skiing', description = 'Winter in Nagano, Japan is absolutely magical and we wanted to share with you some of the best winter activities for your travels! We ate a delicious hot pot in igloos (or Kamakura) and also went skiing and snowboarding on the slopes at Togari Ski Resort (戸狩温泉) in Iiyama (飯山).

