Instagram: https://www.instagram.com/royandaimee/

//NAGANO TRAVEL LINKS:
Ski Resort - https://www.powderhounds.com/Japan/Honshu/Togari-Onsen.aspx
Kamakura festival - https://www.iiyama-ouendan.net/en/special/kamakura/' where id = 'Sn815Aa2YzNOVjrIQNco9';
