update content_bodies set title = 'FARM STAY in JAPAN! - Traditional Japanese travel experience in Akita', description = 'What better way is there to experience Japanese culture than being invited into a local farmers home to hang out and stay the night? On our recent trip to Akita (秋田県), we did a farm homestay in the humble town of Odate (大館市). We stayed with Yamauchi-san and his wife and together we cooked the local cuisine - Kiritanpo (切りたんぽ). 

Kiritanpo is essentially mashed rice, cooked on a stick over an open fire, and then either eaten with a delicious miso glaze, or put in another meal, such as a hotpot - perfect for a chilly winter night! We had a quick trip to an onsen, and afterwards we stayed up late into the night having drinks, laughing and enjoying each others company. 

The next day Yamauchi gave us a personal tour of his town, giving us all the insider knowledge that you couldn''t discover by yourself as a tourist. We even got to see and pet the famous Akita Inu''s (秋田犬)! Even with our limited Japanese speaking ability, Yamauchi-san and his wife were incredibly accomodating and we can''t thank them enough for such a fun experience. 

//FARM STAY LINKS:
Akita farm stay - https://marugoto-odate-eng.amebaownd.com/pages/2086599/page_201603171106

//OUR CAMERA GEAR:
Camera - https://amzn.to/33O8P85
Microphone - https://amzn.to/3nIoZYA

//COME SAY HI!
Instagram: https://www.instagram.com/royandaimee/

Disclaimer: links in this description may be affiliate links. If you click on them and buy a product or service using this link, we may receive a small commission. This is at no extra cost to you! Thank you so much for supporting our channel!' where id = '7aGwVje2e_dB2jqOTIBMH';
update content_bodies set title = 'FARM STAY in JAPAN! - Traditional Japanese travel experience in Akita', description = 'What better way is there to experience Japanese culture than being invited into a local farmer''s home to hang out and stay the night? On our recent trip to Akita (秋田県), we did a farm homestay in the humble town of Odate (大館市). We stayed with Yamauchi-san and his wife and together we cooked the local cuisine - Kiritanpo (切りたんぽ).

Kiritanpo is essentially mashed rice, cooked on a stick over an open fire, and then either eaten with a delicious miso glaze, or put in another meal, such as a hotpot - perfect for a chilly winter night! We had a quick trip to an onsen, and afterwards we stayed up late into the night having drinks, laughing and enjoying each other''s company.

The next day Yamauchi gave us a personal tour of his town, giving us all the insider knowledge that you couldn''t discover by yourself as a tourist. We even got to see and pet the famous Akita Inu''s (秋田犬)! Even with our limited Japanese speaking ability, Yamauchi-san and his wife were incredibly accommodating and we can''t thank them enough for such a fun experience.

//FARM STAY LINKS:
