update content_bodies set title = 'WINTER ONSEN IN JAPAN - Staying in a Japanese inn with hot springs', description = 'We had the amazing opportunity to stay in a traditional Japanese inn (ryokan 旅館) and experience an outdoor onsen (露天風呂) in winter time with snow all around us! If you are ever visiting Japan in winter we would highly recommend this experience! We stayed in Ganiba Onsen in Akita and during our time at the ryokan we also got to experience a traditional multi-course Japanese dinner and breakfast. 

//COME SAY HI!
Instagram: https://www.instagram.com/royandaimee/

//MUSIC FROM: 
Epidemic Sound - https://www.epidemicsound.com/referral/zjyf0a/' where id = 'Bp9lt6x9qIrbgu7anEQCH';
