update content_bodies set title = '日本のロードトリップ | 祖谷渓を探索', description = '祖谷渓は、私たちの日本を巡る3週間のキャンピングカー旅行の目的地でした。
四国という日本の小さな島の一つに、美しい渓谷、かわいらしい小さな村、そして息をのむような景色が広がる山岳地域があります。

私たちは見つけられる限りの穴場の店から食べ物を試し、危険な1車線の道を走り、1800mの高さを誇る三嶺の頂上に登りました！

//気軽に声をかけてください！
Instagram: https://www.instagram.com/royandaimee/
Blog: https://www.roy-and-aimee.com/' where id = 'ETf-NgzU8aOb-pN6Dijxq';
update content_bodies set title = 'JAPAN ROAD TRIP | Exploring Iya Valley', description = 'Iya Valley was a destination on our 3 week campervanning road trip around Japan. On one of Japan''s smaller islands, Shikoku, there is a mountainous region containing beautiful gorges, cute little villages, and breathtaking views.

We tried food from the most hole in the wall shops we could find, drove along potentially dangerous 1-way-only roads, and climbed to the summit of Mt Miune (三嶺), a 1800m tall mountain!

//COME SAY HI!
Instagram: https://www.instagram.com/royandaimee/
Blog: https://www.roy-and-aimee.com/' where id = '_QkuxfaCIvtCiLSlXl8QR';
