update content_bodies set title = '[4K HDR] Exploring the World Heritage Village in Japan - Gokayama Ainokura Village（世界遺産の村 五箇山相倉を探検）', description = 'Ainokura, Gokayama, Toyama Prefecture was nominated as UNESCO World Heritage Site in 1995. It has great scenery of traditional style Japanese country side. The typical style of buildings in this area is called as Gassho-zukuri（合掌造り）. It looks neat triangle shape if you stand in front.' where id = 'hzIML_WBvk2xXlFooCqfj';
