update content_bodies set title = 'An Outdoor Sports Paradise - アウトドアスポーツの楽園 | South Tokushima', description = 'SUP，トレイルランニング，カヤック，サイクリング，サーフィン…。海や山に囲まれた大自然いっぱいの徳島県南部は，まさにアウトドアスポーツの楽園です！
Stand up Paddleboarding, Trail Running, Kayaking, Cycling, Surfing…  Blessed with nature and surrounded by the sea and mountains, South Tokushima is truly an outdoor sports paradise!

