0:00　オープニング

0:04　酒蔵　恵那醸造「鯨波」×酒蔵見学
https://www.kujiranami.jp/

0:25　温泉　大橋酒造「笠置鶴」×岩寿荘
https://k-tsuru.com/

0:42　食　山内酒造「ふかもり」×はなのこ蕎麦　衣月
https://yamauchisyuzou.com/

1:00　和菓子　はざま酒造「恵那山」×にぎわい特産館
https://enasan.jp/

⋱⋰ ⋱⋰ ⋱⋰ ⋱⋰ ⋱⋰ ⋱⋰ ⋱⋰ ⋱⋰ ⋱⋰ ⋱⋰ ⋱⋰ ⋱⋰

中津川市には酒蔵が4つあります。
各酒蔵が代表する銘酒と中津川市の幻想的な冬、
温泉、食、との組み合わせは最高ですよ！！

お酒の風味は造られる地域の水質、天候などに大きく関わります。
中津川市は美味しいお酒が出来る条件が揃っているので
透き通るような美味しいお酒ばかりです！

ぜひ中津川市に来たら飲んでみて下さいね★

Nakatsugawa City is home to four sake breweries.
The combination of each brewery''s signature sake with the city''s magical winter, hot springs, and local cuisine is absolutely perfect!

The flavor of sake is greatly influenced by the region''s water quality, weather, and other factors.
Nakatsugawa City has all the right conditions to produce delicious sake, so you can expect nothing but clear, flavorful drinks!

If you ever visit Nakatsugawa, make sure to try the local sake.

