Walk the Nakasendo and explore the essence of Japan!

Nakatsugawa City sightseeing sample course!

Explore the old streets and buildings that remain along the Nakasendo Trail, and explore the first-hand history by walking through!

There are areas on the Trail where cars cannot go in, which results in preserving the traditional view of the past.

Visit Nakatsugawa City and feel the impressive history that can be experienced only by walking.


岐阜県中津川市の観光モデルコースです！

中山道に残る古い街並みや建物、
実際に歩いて歴史を肌で感じてみて下さい★

中山道は、車が通れない様な所もありますが、
そのおかげで昔の日本当時をそのまま残す事が出来ます。

歩くからこそ感じられる感動をぜひ
体験しに来てください！

ぜひ！中津川市へお越しください！！！

