update content_bodies set title = '【金勝寺　特別体験プログラム紹介動画】KONSHOJI TEMPLE PREMIUM TOUR日本の美と文化を体感できる3つのコンテンツ', description = '滋賀県栗東市にある金勝寺は金勝山の頂上近くにある静寂なたたずまいを見せる天台宗の寺です。約1300 年前に良弁が寺院を創立し、願安が山上に僧侶が集まり修行をする場を建立して国家の平安を祈願し勅願の寺ともなりました。

自然と共生しているお寺としても素晴らしい景観を持ち、歴史ある仏殿と四季折々の植物を数多く見ることができる金勝寺にて澄んだ空気の中、日本の文化と美をテーマにした体験をお楽しみ頂けます。

■苔フィールドワーク
金勝寺は境内に70種類以上の苔が自生する日本でも有数の苔の名所として知られるお寺です。苔の専門家と一緒に多種多様な苔を観察することができます。
Konshoji Temple has become known as one of the best places in Japan for mosses, with more than 70 varieties of mosses growing wild. 
You will do fieldwork to observe a wide variety of mosses with a professional guide.With a loupe and the Konshoji Temple Moss Guide Map in hand, you will enjoy the delicate andmysterious microscopic world of mosses.

■座禅体験
本堂にて、日本の禅文化を象徴する座禅を体験していただけます。精神を統一させることで自分と向き合い深い瞑想から安らぎを見出していただけます。
Why don''t you spend "a time to quietly reflect on your own mind" at the Zazen experience held in the main hall of Kinsho-ji Temple?
Zazen is a method of Buddhist practice in which one faces oneself by sitting in an upright posture and unifying the mind.


■森林浴ヨガ
境内の最も高い位置にある大講堂跡にて自然のエネルギーを感じる外ヨガを体験していただけます。せわしなく過ぎる日常から離れ、自然の中に身を置きありのままの自分を感じる時間を体験ください。
Experience outdoor yoga for the power of nature at the remains of the main school hall located at the highest spot at the historic Konshoji Temple.
Get away from all the hustle and bustle, immerse yourselves in nature,
and free your body and spirit. It’s also an extraordinary experience to feel the connection between yourselves and the external world with no borders.


ツアーのお問い合わせ・主催
一般社団法人栗東市観光協会
滋賀県栗東市手原3丁目1-30(手原駅2階)
TEL：077-551-0126／FAX：077-551-6158　
MAIL：tateba.ritto@gmail.com' where id = '1Tq18fyE-vW67Yp8lMtN1';
update content_bodies set title = '[KONSHOJI TEMPLE PREMIUM TOUR] A Video Introduction to the Special Experience Program - Three Contents to Experience Japan''s Beauty and Culture', description = 'Konshoji Temple, located in Ritto City, Shiga Prefecture, is a tranquil Tendai sect temple situated near the summit of Mount Konsho. Founded about 1300 years ago by Ryoben, the temple became a place where monks gathered for training on the mountain, praying for national peace and becoming a temple of imperial decree.

As a temple that coexists with nature, Konshoji Temple boasts a stunning landscape, allowing visitors to see its historic Buddha hall and a variety of seasonal plants. Here, you can enjoy experiences themed around Japanese culture and beauty in the clear air.

■ Moss Fieldwork
Konshoji Temple is known as one of the best places in Japan for mosses, with more than 70 varieties of moss growing wild on its grounds. You will do fieldwork to observe a wide variety of mosses with a professional guide. With a loupe and the Konshoji Temple Moss Guide Map in hand, you will enjoy the delicate and mysterious microscopic world of mosses.

■ Zazen Experience
You can experience Zazen, which symbolizes Japanese Zen culture, in the main hall. By unifying your mind, you can face yourself and find peace through deep meditation. Why don''t you spend "a time to quietly reflect on your own mind" at the Zazen experience held in the main hall of Kinsho-ji Temple? Zazen is a method of Buddhist practice in which one faces oneself by sitting in an upright posture and unifying the mind.

■ Forest Bathing Yoga
Experience outdoor yoga to feel the energy of nature at the remains of the main school hall located at the highest spot at the historic Konshoji Temple. Get away from all the hustle and bustle, immerse yourselves in nature, and free your body and spirit. It’s also an extraordinary experience to feel the connection between yourselves and the external world with no borders.

Tour Inquiries & Organizer
Ritto City Tourism Association
3-1-30 Tehara, Ritto City, Shiga Prefecture (2nd floor of Tehara Station)
TEL: 077-551-0126 / FAX: 077-551-6158
MAIL: tateba.ritto@gmail.com' where id = '7F_Ix23OApWmSKIDu_BLR';
