update content_bodies set title = '【兵庫県赤穂市日本遺産PR動画】Sel de la vie -Traveling is the salt of life-', description = 'Sel de la vie(セル ドゥ ラ ヴィ)は「人生の塩」を意味するフランス語です。
2人のシェフがキッチンバスで街をめぐり、赤穂の自然・文化・人・食材と触れ合い、最高の料理でもてなします。塩のスパイスに、赤穂の魅力を引き立てるハートフルムービーです。
---------------------------------------------------------------------------------------------------------------------------------------------------------------
Two chefs ride the kitchen bus across Hyogo''s Ako region eager to sample the fresh produce that the area is renowned for. 
▼Let’s go for a pinch of Ako’s salt！▼
https://ako-kankou.jp/salt-city/

Ako, in 2019, became a certified Japan Heritage site. There are 41 salt-related historical and cultural heritages located in Ako.
---------------------------------------------------------------------------------------------------------------------------------------------------------------
AKO ONSEN【 Feel Ako Time】
I yearn to take a trip – to some unknown town
Walking on the seashore for the first time in a long while 
The scent of the tide, light dancing on the waves knock softly on the door to my heart.
Beyond the horizon, I’m reminded of distant memories
▶https://youtu.be/who6XBy0KqA
---------------------------------------------------------------------------------------------------------------------------------------------------------------

【受賞歴】
「第68回兵庫県広報コンクール」特選受賞
「第3回日本国際観光映像祭」最優秀日本遺産映像賞受賞、ツーリズムプロダクト部門優秀作品

#日本遺産　#赤穂市　#JapanHeritage' where id = 'P3vDXy5XpBiGJWpvKNEki';
update content_bodies set title = '[Hyogo Prefecture Ako City Japan Heritage PR Video] Sel de la vie -Traveling is the salt of life-', description = 'Sel de la vie means ''the salt of life'' in French.
Two chefs ride the kitchen bus across the city, interacting with Ako''s nature, culture, people, and ingredients, and serving the best dishes. This heartwarming movie enhances the charm of Ako with the spice of salt.
---------------------------------------------------------------------------------------------------------------------------------------------------------------
Two chefs ride the kitchen bus across Hyogo''s Ako region eager to sample the fresh produce that the area is renowned for.
