update content_bodies set title = '【SL&FUN】SL冬の湿原号と釧路の大地　編【4K】', description = '沿線周辺の冬の観光情報はこちらから　https://ja.kushiro-lakeakan.com/sl-kanko/
釧網本線　釧路－標茶間を約１時間半かけひた走るSL冬の湿原号は北海道で唯一のSL。
2022年から2023年にかけて全客車をリニューアル。SLが持つレトロ感やノスタルジックな雰囲気がより一層感じられる。
そんなSL冬の湿原号が運行する、ひがし北海道・釧路（くしろ）地域には、北海道内でもここでしか味わえない体験がたくさん！

【制作】くしろ地域冬季観光開発協議会
　釧路市、釧路町、標茶町、弟子屈町、鶴居村
　釧路観光連盟、北海道旅客鉄道株式会社、釧路総合振興局' where id = 'WRqRrTa5eGXIkC9lPSILu';
update content_bodies set title = '[SL&FUN] SL Winter Wetland Train and the Land of Kushiro [4K]', description = 'For winter tourism information around the railway line, visit here: https://ja.kushiro-lakeakan.com/sl-kanko/
The SL Winter Wetland Train runs for about an hour and a half between Kushiro and Shibecha, and is the only SL in Hokkaido.
From 2022 to 2023, all passenger cars have been renewed. The retro feel and nostalgic atmosphere of the SL can be felt even more strongly.
In the eastern Hokkaido region of Kushiro, where the SL Winter Wetland Train operates, there are many unique experiences that can only be enjoyed here in Hokkaido!

[Produced by] Kushiro Region Winter Tourism Development Council
