update content_bodies set title = '01 Felicidad "フェリシダ" 幸せ（静岡県森町）', description = 'Morimachi Tourism Short Movie 01
「Felicidad」 "フェリシダ" 幸せ

静岡県森町
富士山のある静岡県の西部に位置するこの町は、
美しい自然や伝統を大切にする人々が暮らしており、
遠州の小京都と呼ばれています。

そんな人々の暮らしを1年に渡り撮影した動画を、
森町三倉地区・大久保集落にスペインから移住した、
フランセスク・プラナスさんのナレーションと共に
ショートムービーにしました。


「森町に棲む」

ご覧になり、ぜひ一度森町を訪れて下さい。
きっとここには、あなたの心に響く何かがあるはずです。


製作　　　森町ツーリズム研究会
　　　　　美しい茶園でつながるプロジェクト推進部会

撮影編集　コバヤシデザイン　小林成彦
撮影協力　森町地域おこし協力隊　岩瀬進哉
ﾅﾚｰｼｮﾝ　　フランセスク・プラナス
書　　　　森町役場 産業課　三倉忠徳
BGM　　　HURT RECORD


静岡県森町
「鍛治島 半夏生への小径」
「大久保 立体集落への茶園」
ガイドマップのリンク
https://www.town.morimachi.shizuoka.jp/_files/00011556/20170602machichaen-2.pdf#search=%27%E5%8D%8A%E5%A4%8F%E7%94%9F%E3%81%B8%E3%81%AE%E5%B0%8F%E5%BE%84%27' where id = 'cVGwqPlyW9NdjL079BWPw';
update content_bodies set title = '01 Felicidad "Felicidad" Happiness (Morimachi, Shizuoka Prefecture)', description = 'Morimachi Tourism Short Movie 01
"Felicidad" "フェリシダ" Happiness

Morimachi, Shizuoka Prefecture
This town, located in the western part of Shizuoka Prefecture with Mount Fuji, is home to people who cherish beautiful nature and traditions, and is called the small Kyoto of Enshu.

We created a short movie capturing the lives of these people over the course of a year, narrated by Francesc Planas, who moved from Spain to the Mikura area of Morimachi and the Okubo settlement.

"Living in Morimachi"

Please watch it and consider visiting Morimachi at least once. Surely, there is something here that will resonate with your heart.

Produced by: Morimachi Tourism Research Group
Project Promotion Committee Connecting through Beautiful Tea Gardens

Filming and Editing: Kobayashi Design, Naruhiko Kobayashi
Filming Cooperation: Morimachi Regional Revitalization Cooperation Team, Shunya Iwase
Narration: Francesc Planas
Writing: Morimachi City Hall, Industry Division, Tadanori Mikura
BGM: HURT RECORD

Morimachi, Shizuoka Prefecture
"Kaji Island Path to Hange-shō"
"Okubo Tea Garden to the Three-Dimensional Settlement"
Link to the guide map
https://www.town.morimachi.shizuoka.jp/_files/00011556/20170602machichaen-2.pdf#search=%27%E5%8D%8A%E5%A4%8F%E7%94%9F%E3%81%B8%E3%81%AE%E5%B0%8F%E5%BE%84%27' where id = 'qXaODUxu7p9aSHE5G2lLM';
update content_bodies set title = 'Nature tourism IN Hida-Osaka 飛騨小坂', description = '飛騨小坂は岐阜県の中部に位置し、南は下呂温泉、北は飛騨高山などの大型観光地のちょうど中間にあるひっそりとした山村です。小さな町ですが、活火山御嶽山の恵みを受けて３つの異なる温泉（湯屋温泉・下島温泉・濁河温泉）を擁し、深く刻み込まれた谷筋には落差５ｍ以上の滝が216か所ある日本一滝の多い町です。そんな、国内でも有数の自然資源を堪能できるアクティビティーが飛騨小坂にはたくさんあるんです。春には道の駅はなもも沿いに咲くハナモモの花を愛でながらE-Bikeでサイクリング、秋には色づく森のの中でハンモックに揺られながらオシャレにカフェを楽しむ。冬には雪にまみれサウナを楽しんだり、結氷した滝（氷瀑）を訪ねて歩く冬の滝めぐりも楽しい。そして夏は盛りだくさん、渓流釣り、キャンプ、シャワークライミング、滝めぐり。思い思いの楽しみ方で遊びつくせます。下呂から車で30分、高山から40分。決して交通の便の良い場所では無いです。日帰りではなく1泊してお越しいただくことをお勧めします。一度訪れたらきっと病みつきになるはずです。
Full video that shows what you can enjoy in Hida-Osaka throughout the year. Hida-Osaka is a small town at the west foot of Mt. Ontake with the biggest number of waterfalls in Japan. There are 216 waterfalls higher than 5 meters around the area, and 216WORKS is the only guide service company that runs waterfall trekking tours in the region. I''m so honored to be one of the guides in the company. All tours and activities are available or accessible via 216WORKS. For more info, please visit our website: https://www.216works.com/ and send message. All tours and activities are available or accessible via 216WORKS, Guide Service Office in Hida-Osaka. Website: https://www.216works.com/ Hida-Osaka is not only about the waterfall trekking, but there are many other things you can do thanks to the natural gift given by our mother mountain Mt. Ontake. #japan #guide #hidaosaka #216WORKS #japão #guia #fishing #pesca #japanesenature #naturetour #ecotour #cidadedascahoeiras #caminhada #trilha #trekking #hiking' where id = '48VlvJgax-q0304flk53T';
update content_bodies set title = 'Nature tourism IN Hida-Osaka', description = 'Hida-Osaka is a quiet mountain village located in the central part of Gifu Prefecture, exactly halfway between the large tourist destinations of Gero Onsen to the south and Hida Takayama to the north. Although it is a small town, it boasts three different hot springs (Yuyama Onsen, Shimojima Onsen, and Dakkagawa Onsen) thanks to the blessings of the active volcano, Mt. Ontake. It is also the town with the most waterfalls in Japan, featuring 216 waterfalls with a drop of over 5 meters carved deeply into the valleys. Hida-Osaka offers many activities to enjoy its abundant natural resources, which are among the best in the country. In spring, you can cycle along the Hanamomo flowers blooming by the roadside with an E-Bike, and in autumn, you can enjoy a stylish café while swaying in a hammock amidst the colorful forest. In winter, you can enjoy a sauna surrounded by snow or take a winter waterfall tour to visit frozen waterfalls (ice falls). Summer is packed with activities such as stream fishing, camping, shower climbing, and waterfall tours. You can enjoy it in your own way. It is a 30-minute drive from Gero and 40 minutes from Takayama. It is not a place with convenient transportation, so we recommend staying overnight rather than just a day trip. Once you visit, you will surely become addicted to it.
Full video that shows what you can enjoy in Hida-Osaka throughout the year. Hida-Osaka is a small town at the west foot of Mt. Ontake with the biggest number of waterfalls in Japan. There are 216 waterfalls higher than 5 meters around the area, and 216WORKS is the only guide service company that runs waterfall trekking tours in the region. I''m so honored to be one of the guides in the company. All tours and activities are available or accessible via 216WORKS. For more info, please visit our website: https://www.216works.com/ and send message. All tours and activities are available or accessible via 216WORKS, Guide Service Office in Hida-Osaka. Website: https://www.216works.com/ Hida-Osaka is not only about the waterfall trekking, but there are many other things you can do thanks to the natural gift given by our mother mountain Mt. Ontake. #japan #guide #hidaosaka #216WORKS #japão #guia #fishing #pesca #japanesenature #naturetour #ecotour #cidadedascahoeiras #caminhada #trilha #trekking #hiking' where id = '8JSlSPvYgA0PdzghoJdJj';
update content_bodies set title = '【屋久島】Digest : 神秘の森の先にある新しい屋久島 - A Fulfilling Journey 生命が満たされる旅', description = 'A Fulfilling Journey 生命が満たされる旅
https://yakushima-journey.com/jp/

1993年、日本で初めて世界自然遺産に登録された屋久島。
世界的にも有名な類い稀な自然環境を誇る山や森はもちろんのこと、この島の里には、楽しいアクティビティと美味しい食事、豊かな文化が溢れています。
あなたは誰とどんなルートを旅しますか？
あなただけの屋久島の魅力を、ぜひ発見してみてください。

公式サイト | Learn more about Yakushima
日本語 : https://yakushima-journey.com/jp
English : https://yakushima-journey.com

Produced by Kagoshima Prefectural Yakushima Office
http://www.pref.kagoshima.jp/aa02/chiiki/kumage/soshiki/yakushima.html' where id = 'djOI3qIfUF9-wX119kbqT';
update content_bodies set title = '[Yakushima] Digest: A New Yakushima Beyond the Mysterious Forest - A Fulfilling Journey', description = 'A Fulfilling Journey
https://yakushima-journey.com/jp/

In 1993, Yakushima was registered as Japan''s first World Natural Heritage site.
In addition to its globally renowned and unique natural environment of mountains and forests, this island is filled with fun activities, delicious food, and rich culture.
Who will you travel with and what route will you take?
Be sure to discover the charm of Yakushima that is uniquely yours.

Official Site | Learn more about Yakushima
Japanese: https://yakushima-journey.com/jp
English: https://yakushima-journey.com

Produced by Kagoshima Prefectural Yakushima Office
http://www.pref.kagoshima.jp/aa02/chiiki/kumage/soshiki/yakushima.html' where id = '4DiJhtZT30m508RccWSmE';
