update content_bodies set title = 'BIRD''S EYE3「２６　八ッ場ダム周辺の風景①」｜建設企画課｜群馬県', description = '※群馬テレビで令和元年９月２８日・２９日に放映したものです。

私達の生活に欠かせない土木施設。県内には重要文化財に指定されたもの、最新の技術を駆使したものなど、将来に語り継ぐ価値のある土木施設が数多く存在します。
これら土木施設の役割や魅力を広く伝え、また将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組を制作し放送することとなりました。
ドローンで撮影した映像などを駆使し、土木施設ならではのスケール感・ダイナミック感をお伝えします。

群馬県長野原町の八ッ場ダムは、長きにわたる建設期間を終えようとしています。
それは、いま目にできる風景の見納めの時でもあるのです。これから新しく生まれ変わる長野原町。その前に、この八ッ場ダム周辺の風景をお楽しみください。

問い合わせ先：建設企画課（027-226-3531）' where id = 'U8FnOpj48E_lXmEty-nIU';
update content_bodies set title = 'BIRD''S EYE3 ''26 Yamba Dam Surroundings Landscape ①'' | Construction Planning Division | Gunma Prefecture', description = 'This was broadcasted on Gunma TV on September 28 and 29, 2019.

Civil engineering facilities are essential to our lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties, as well as those utilizing the latest technologies, all of which hold value to be passed down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will bear the future, we have decided to produce and broadcast a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the unique scale and dynamism of civil engineering facilities.

The Yamba Dam in Naganohara Town, Gunma Prefecture, is nearing the end of its long construction period.
This is also a time to take a final look at the scenery that can be seen now. Naganohara Town is about to be reborn anew. Before that, please enjoy the scenery around the Yamba Dam.

Contact: Construction Planning Division (027-226-3531)' where id = 'AgqxAzvlI-oHq6pgXqmf0';
update content_bodies set title = 'BIRD''S EYE3「３１　日本国道最高地点より望む風景」｜建設企画課｜群馬県', description = '※群馬テレビで令和元年１１月２日・３日に放映したものです。

私達の生活に欠かせない土木施設。県内には重要文化財に指定されたもの、最新の技術を駆使したものなど、将来に語り継ぐ価値のある土木施設が数多く存在します。
これら土木施設の役割や魅力を広く伝え、また将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組を制作し放送することとなりました。
ドローンで撮影した映像などを駆使し、土木施設ならではのスケール感・ダイナミック感をお伝えします。

群馬県と長野県の県境付近に国道２９２号には、白根山の山頂近くに日本全国に敷かれた国道の中で最も高い場所があります。最高地点の標高は2,172メートルで、天候によっては雲海を望むことができるこの場所には、多くの観光客が訪れます。
平野部より気温がグンと低く、お出かけの際には少し厚めの服装がお勧めです。

問い合わせ先：建設企画課（027-226-3531）' where id = 'GD5EE1WCYmhADTUHRMC7H';
update content_bodies set title = 'BIRD''S EYE3 ''31 View from the Highest Point of National Route in Japan'' | Construction Planning Division | Gunma Prefecture', description = 'This was broadcasted on Gunma TV on November 2nd and 3rd, 2019.

Civil engineering facilities are essential to our daily lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties and those that utilize the latest technologies, all of which hold value to be passed down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest among the children who will carry the future, we have decided to produce and broadcast a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the unique scale and dynamism of civil engineering structures.

Near the border between Gunma and Nagano Prefectures, National Route 292 has the highest point among national routes laid out across Japan, located close to the summit of Mount Shirane. The elevation of the highest point is 2,172 meters, and depending on the weather, visitors can enjoy a view of the sea of clouds, attracting many tourists.
The temperature is significantly lower than in the plains, so it is recommended to wear slightly thicker clothing when visiting.

Contact: Construction Planning Division (027-226-3531)' where id = 'gK519l75kfoylOrLWtegC';
update content_bodies set title = 'BIRD''S EYE3「３２　「万座三叉路」を望む風景」｜建設企画課｜群馬県', description = '※群馬テレビで令和元年１１月９日・１０日に放映したものです。

私達の生活に欠かせない土木施設。県内には重要文化財に指定されたもの、最新の技術を駆使したものなど、将来に語り継ぐ価値のある土木施設が数多く存在します。
これら土木施設の役割や魅力を広く伝え、また将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組を制作し放送することとなりました。
ドローンで撮影した映像などを駆使し、土木施設ならではのスケール感・ダイナミック感をお伝えします。

万座三叉路は群馬県吾妻郡嬬恋村に位置し、国道292号と県道牧干俣線が交わる交差点です。国道292号は、群馬県長野原町から新潟県上越市までを結ぶ路線であり、県道牧干俣線は、長野県上高井郡高山村より群馬県吾妻郡嬬恋村に至る一般県道です。
日本風景街道の関東第１号として「浅間・白根・志賀さわやか街道」としても親しまれています。景観もよく、秋の行楽シーズンはドライブに最適です。

問い合わせ先：建設企画課（027-226-3531）' where id = 'jHs6ILXlqLg6RFAvlqplC';
update content_bodies set title = 'BIRD''S EYE3 "32 ''Scenery Overlooking Manza Intersection''" | Construction Planning Division | Gunma Prefecture', description = 'This was broadcasted on Gunma TV on November 9 and 10, 2019.

Civil engineering facilities are essential to our lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties, as well as those that utilize the latest technologies, all of which have value worth passing down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will carry the future, we have decided to produce and broadcast a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the unique scale and dynamism of civil engineering structures.

Manza Intersection is located in Tsumagoi Village, Agatsuma District, Gunma Prefecture, where National Route 292 and Prefectural Road Maki-Hanamata Line intersect. National Route 292 connects Nagano Prefecture''s Nagano Town to Joetsu City in Niigata Prefecture, while the Prefectural Road Maki-Hanamata Line is a general prefectural road that runs from Takayama Village in Nagano Prefecture to Tsumagoi Village in Agatsuma District, Gunma Prefecture.
It is also known as the "Asama, Shirane, and Shiga Refreshing Road" as the first scenic road in Kanto. The scenery is beautiful, making it ideal for drives during the autumn leisure season.

Contact: Construction Planning Division (027-226-3531)' where id = 'yX2UGOqoygmaJCQ6m2cka';
update content_bodies set title = 'BIRD''S EYE3「３５　越本床固群から望む風景」｜建設企画課｜群馬県', description = '※群馬テレビで令和元年１１月３０日・１２月１日に放映したものです。

私達の生活に欠かせない土木施設。県内には重要文化財に指定されたもの、最新の技術を駆使したものなど、将来に語り継ぐ価値のある土木施設が数多く存在します。
これら土木施設の役割や魅力を広く伝え、また将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組を制作し放送することとなりました。
ドローンで撮影した映像などを駆使し、土木施設ならではのスケール感・ダイナミック感をお伝えします。

片品村を流れる片品川には越本床固群があります。床固（とこがため）とは、川の流れにより川底や護岸が削られることを防ぐ土木施設です。
私たちが日常を過ごすなかで当たり前にみているこの構造物ですが、実際に近くで見ると魚の遡上を妨げない魚道など、自然に配慮した工夫がなされているのです。

問い合わせ先：建設企画課（027-226-3531）' where id = 'EYRzRpP_XkNtEPLrkOorE';
update content_bodies set title = 'BIRD''S EYE3 ''35 View from the Koshimoto Toko-gata Group'' | Construction Planning Division | Gunma Prefecture', description = 'This was broadcasted on Gunma TV on November 30 and December 1, 2019.

Civil engineering facilities are essential to our daily lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties and those that utilize the latest technologies, all of which hold value to be passed down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will carry the future, we have decided to produce and broadcast a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the scale and dynamism unique to civil engineering facilities.

The Katashina River, which flows through Katashina Village, features the Koshimoto Toko-gata Group. Toko-gata refers to civil engineering structures that prevent the riverbed and embankments from being eroded by the flow of the river.
While we see this structure as a normal part of our daily lives, a closer look reveals thoughtful designs, such as fishways that do not hinder the upstream migration of fish, demonstrating consideration for nature.

Contact: Construction Planning Division (027-226-3531)' where id = 'HIO3w2442tlsQSqL3sb1P';
update content_bodies set title = 'BIRD''S EYE3「３８　上毛電気鉄道沿線の風景」｜建設企画課｜群馬県', description = '※群馬テレビで令和元年１２月２１日・２２日に放映したものです。

私達の生活に欠かせない土木施設。県内には重要文化財に指定されたもの、最新の技術を駆使したものなど、将来に語り継ぐ価値のある土木施設が数多く存在します。
