update content_bodies set title = 'BIRD''S EYE3 ''38 Scenery Along the Jomo Electric Railway'' | Construction Planning Division | Gunma Prefecture', description = 'This was broadcast on Gunma TV on December 21 and 22, 2019.

Civil engineering facilities are essential to our lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties, as well as those that utilize the latest technologies, all of which have value worth passing down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will carry the future, we have decided to produce and broadcast a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the unique scale and dynamism of civil engineering facilities.

The Jomo Electric Railway connects Maebashi City and Kiryu City in Gunma Prefecture. From the train windows, you can see Mount Akagi in the distance.
A feature of the Jomo Electric Railway is the cycle train, which allows bicycles to be brought on board. Additionally, decorations on the train body and inside the train are changed according to the seasons and events to entertain users.

Contact: Construction Planning Division (027-226-3531)' where id = 'Tj6G9KmPMuiFZ-rzPrgD6';
update content_bodies set title = 'BIRD''S EYE3「３９　Gメッセ群馬周辺の風景」｜建設企画課｜群馬県', description = '※群馬テレビで令和２年１月１１日・１２日に放映したものです。

私達の生活に欠かせない土木施設。県内には重要文化財に指定されたもの、最新の技術を駆使したものなど、将来に語り継ぐ価値のある土木施設が数多く存在します。
これら土木施設の役割や魅力を広く伝え、また将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組を制作し放送することとなりました。
ドローンで撮影した映像などを駆使し、土木施設ならではのスケール感・ダイナミック感をお伝えします。

令和２年最初の放送でお送りするのは、今年４月、高崎市にオープンする大型コンベンション施設「Ｇメッセ群馬」です！
Ｇメッセ群馬は11万㎡の敷地に、柱のない構造の大展示場や大小１７の会議スペースなどを擁する、北関東最大規模の大型コンベンション施設です。
今回は、完成に向け日々働いている約４００名の作業員たちの姿と、建設中のＧメッセ群馬の１２月の様子を紹介します。
大型施設が人の力によってつくられ、また、完成後も利用する人によって街は進化と躍進を続けていきます。新しい時代の幕開けを感じながら、Ｇメッセ群馬を中心とした高崎市の景色をご覧ください。

問い合わせ先：建設企画課（027-226-3531）' where id = 'mUKKp0TLOMuG-pDyCeOUA';
update content_bodies set title = 'BIRD''S EYE3 ''39 Scenery around G-Messe Gunma'' | Construction Planning Division | Gunma Prefecture', description = 'This was broadcasted on Gunma Television on January 11 and 12, 2020.

Civil engineering facilities are essential to our lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties, as well as those utilizing the latest technologies, all of which hold value to be passed down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will carry the future, we have produced a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the unique scale and dynamism of civil engineering facilities.

The first broadcast of 2020 will feature the large convention facility ''G-Messe Gunma,'' which will open in Takasaki City this April!
G-Messe Gunma is the largest convention facility in the northern Kanto region, covering an area of 110,000 square meters, featuring a large exhibition hall with no columns and 17 meeting spaces of various sizes.
This time, we will introduce the approximately 400 workers who are working daily towards its completion, as well as the state of G-Messe Gunma under construction in December.
Large facilities are created by human effort, and after completion, the city continues to evolve and advance through the people who use them. While feeling the dawn of a new era, please enjoy the scenery of Takasaki City centered around G-Messe Gunma.

