この度、広島県福山市の移住・定住をテーマとしたシティプロモーション動画を制作させていただきました。

福山市は、広島県で人口が２番目に多い街で、北には山や自然が広がり、南には穏やかな瀬戸内海の景色が広がります。市内は程よい都会で、新幹線も停車するため、お出かけや買い物にも便利な街です。特に江戸時代に栄えた鞆の浦の景観や、穏やかな時間の流れの中に身を置くと、とても居心地が良く、多くの観光客を惹きつけることに納得できます。今回、実際に首都圏や県外から福山市へ移住された子育て世代の方々に貴重なお話を伺うことができました。

福山市への移住・旅行を検討されている方は、是非動画を観て、実際に足を運んでみてください！

ご出演協力 ：NIPPONIA 鞆 港町 鳥井様 柿木様、夫婦の会社「コト暮らし」代表 長田様、福山市在住 山本様
協力：広島県、福山市 
アドバイザー：森ガキ侑大監督
監督、撮影、編集 ：KoSEI（浮田 昂成）

撮影地 : 広島県福山市
（今回、広島県が主催するプロジェクトにて映像をプロデュースさせて頂きました。）' where id = 'pxogXOyGml8bMwsLL6oaG';
