「侍が和楽器（尺八）をカッコよく演奏する」という異色のMV作品をプロデュースさせて頂きました。葉加瀬太郎さんの代表曲「情熱大陸」を尺八演奏家の川村葵山さんにカバー制作して頂きました。力強い尺八の演奏とユニークな映像を楽しんで頂きたいと思っております。川村さんは普段他にも、数々の楽曲をYouTubeで披露されています。▼https://www.youtube.com/channel/UCpt9jZEbqGWpxUt1MDc4Ygg

今作品は、メディアにも取り上げて頂きました！
