I had the opportunity to produce a unique music video featuring a samurai playing traditional Japanese instruments (shakuhachi) in a cool way. The cover of Hakase Taro''s representative song “JONETSU TAIRIKU” was created by shakuhachi player Kizan Kawamura. I hope you enjoy the powerful shakuhachi performance and unique visuals. Kizan also showcases various songs on YouTube. ▼https://www.youtube.com/channel/UCpt9jZEbqGWpxUt1MDc4Ygg

