update content_bodies set title = '北海道大沼グレートラン・ウォーク 〝 health beauty power 〟', description = '「 北海道大沼グレートラン・ウォーク２０２４ 」　’24.10.6（日）開催決定！

2023年10月。５年ぶりに開催された北海道七飯町大沼のランニング大会「グレートラン・ウォーク」（通称：グレラン / GR ）

〝 健康は health、美しく beauty、力強い power 〟 をスローガンに表現された2023年大会の様子をプロモーションビデオとして映像化。

その一歩は「心と体の健康となり」その姿勢は「より美しく軽やかで」チャレンジした自分に「力強い自信とエネルギー」をもたらす。

舞台となる七飯町の大沼国定公園、駒ヶ岳、大沼湖畔。大会スローガンにふさわしく雄大で繊細な美しいランニング（ウォーキング）環境はランナー（ウォーカー）にとって特別な場所となるでしょう。

そして・・・

今年の「 北海道大沼グレートラン・ウォーク２０２４ 」は、２０２４年１０月６日（日）開催が決定！！
エントリーは、６月中旬を予定しています。

大会要項、エントリーなど今後の情報は、以下のホームページ等で発表されます。

Movie:FOLPHOTO

北海道大沼グレートラン・ウォーク公式HP
http://i-sam.co.jp/greatrun_walk/ 

