update content_bodies set title = 'Hokkaido Onuma Great Run & Walk "health beauty power"', description = '"Hokkaido Onuma Great Run & Walk 2024" is confirmed to be held on October 6, 2024 (Sunday)! 

In October 2023, the running event "Great Run & Walk" (commonly known as GR) was held in Onuma, Nanae Town, Hokkaido for the first time in five years. 

The 2023 event was captured in a promotional video, expressing the slogan "Health is health, beautiful is beauty, and powerful is power." 

Each step becomes "health for the mind and body," and the posture becomes "more beautiful and graceful," bringing "strong confidence and energy" to those who challenge themselves. 

The stage is set in Onuma National Park, Mount Komagatake, and along the shores of Lake Onuma. The grand and delicate beautiful running (walking) environment befitting the event''s slogan will become a special place for runners (walkers). 

And... 

This year''s "Hokkaido Onuma Great Run & Walk 2024" is confirmed to be held on October 6, 2024 (Sunday)! 
Entries are expected to open in mid-June. 

Details about the event, entries, and future information will be announced on the following website and others. 

Movie: FOLPHOTO 

