I filmed a non-verbal documentary over three seasons in the Lake Akan Onsen area of Hokkaido, which offers a wealth of captivating features that satisfy your desire for knowledge and exploration of Ainu culture. Additionally, many traditional Japanese artisans contribute to the creation of this unique atmosphere. This film captures the beautiful nature, Ainu culture and traditions, as well as the passion of the people living there.

