update content_bodies set title = 'Akan Soul', description = 'Akan Soul, filmed over three seasons in autumn, winter, and summer for a total of one month. 
This is a non-verbal documentary that follows the daily life of the Ainu culture in the Lake Akan Onsen area of Hokkaido. ☺️ It was a very challenging attempt to convey the stories woven by people''s daily lives without words or explanations. 
Through this work, I was able to connect with many people and learn deeply about the culture.

Once again, I felt the desire to create works that move my heart with time and passion! 
A non-verbal documentary filmed over three seasons in the Lake Akan Onsen area of Hokkaido. 
Captivated by the beautiful nature, the woodcarvers of the Lake Akan Onsen area, the people living their lives, the Ainu culture and traditions, and the passion of the people who live there, I turned the camera on.

Lake Akan Onsen: http://ja.kushiro-lakeakan.com 
Akan Lake Ainu Kotan: https://www.akanainu.jp 
Akan Lake Ainu Theater Ikoro: https://www.akanainu.jp/about/ikoro 
Tofu Kobo Marufuku: https://ja.kushiro-lakeakan.com/eat_souvenir/16078/

I would like to express my gratitude once again to everyone who cooperated in the production of this video. 
I learned a lot and gained many insights myself, thank you!!!

