update content_bodies set title = '【ミッドナイトおおいた】おんせん県の人を知る。おおいたをもっと好きになる。 vol.2 full [公式/大分県]', description = '＜ミッドナイトおおいた とは＞
温泉といえば大分県。
だけど、温泉だけじゃない“おおいた県”
ここには、夕暮れから深夜にかけて
ゆったり・じっくり過ごせる最高のスポットが勢ぞろいしています。
来たらきっと分かる、「ミッドナイトまで楽しめる街」 。
初めての人も、来たことのある人も、
『ちょっと気になる』大分県の夜の魅力を、掘り下げてご紹介します。

https://midnight.visit-oita.jp/

■ミッドナイトおおいた×カルチャー
おんせん県おおいたのまだ見ぬ夜の魅力を、人・場所・食に焦点を当ててドキュメンタリータッチでご紹介します。
日が暮れていく街並み・人々が行き交う雑踏・あかりが灯る飲み屋街…すると、大分県の夜を楽しむ人々の生き生きとした声が入ってくる。
「大分県の夜」が、彼らにとってどんな存在なのか、なぜ唯一無二なのか、なぜ観光客の人々がそれらを体験するべきなのか。
まだ見ぬ大分県の魅力は、人から溢れ出てくるものだった…！
大分県に来たことのある方もまだない方も、まだ見ぬ大分県の魅力にはまるはず。

【ミッドナイトおおいた】おんせん県の人を知る。おおいたをもっと好きになる。 vol.1 full [公式/大分県]
https://youtu.be/ofdWC5arnjE

【ミッドナイトおおいた】おんせん県の人を知る。おおいたをもっと好きになる。 vol.2 full [公式/大分県]
https://youtu.be/DcanwVkYYNM

