update content_bodies set title = 'Presentation Video of the 2021 Tourism Business Meeting ③ (Nakatsu City)', description = 'Nakatsu City is a place full of charm, where the beautiful gorge from the source of the Yamakuni River to its mouth intertwines with the history of the castle town. There are historical sites such as Nakatsu Castle Town, associated with military strategist Kuroda Kanbei and Yukichi Fukuzawa, as well as the Japan Heritage site, Yabakei, known for its stunning landscapes created by bizarre rock formations. The Maple Yabakei Cycling Road is a popular spot where you can experience the scenery and history of Yabakei.' where id = 'mFw1QfvleNcB5pTnv4-l5';
